1	package clinical
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// ---- 测试基础设施 ----
10	
11	type fakeClock struct{ t time.Time }
12	
13	func newTestStore(t *testing.T) (*Store, *fakeClock) {
14		t.Helper()
15		clk := &fakeClock{t: time.Date(2026, 1, 1, 9, 0, 0, 0, time.UTC)}
16		dir := t.TempDir()
17		s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
18		if err != nil {
