233		}
234		if hist == nil || len(hist.Versions) != 2 {
235			t.Fatalf("history = %+v", hist)
236		}
237		if hist.Versions[0].Content != "旧诊断" || hist.Versions[0].Reason != "" {
238			t.Fatalf("v1 mutated: %+v", hist.Versions[0])
239		}
240		if hist.Versions[1].PrevID != v1.ID {
241			t.Fatal("version link lost")
242		}
243	
244		eventsBefore := len(chart.AuditEvents)
245		// 基于过期版本号更正：拒绝且保持现状，不产生事件。
246		if _, err := s.CorrectRecord(doc, r.ID, 1, "抢占更正", "并发"); !errors.Is(err, ErrConflict) {
247			t.Fatalf("stale correction err = %v, want ErrConflict", err)
248		}
249		chart2, _ := s.Chart(doc, pid)
250		if len(chart2.AuditEvents) != eventsBefore {
251			t.Fatal("failed correction generated an audit event")
252		}
253		if hist2 := findHistory(chart2, r.ID); hist2 == nil || hist2.CurrentVersion.Content != "新诊断" || len(hist2.Versions) != 2 {
254			t.Fatal("state changed after failed correction")
255		}
256	
257		// 以当前版本号继续更正成功，链继续延伸。
258		v3, err := s.CorrectRecord(doc2, r.ID, 2, "最终诊断", "补充检查")
